E1.css:
[data-ui-unit="E1"].e1-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 54px;
  width: 100%;
  padding: 8px 0;
}

[data-ui-unit="E1"] .e1-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--ink);
  margin: 0;
  white-space: nowrap;
}

[data-ui-unit="E1"] .e1-tools {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-shrink: 0;
}

[data-ui-unit="E1"] .e1-tool-btn {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

[data-ui-unit="E1"] .e1-tool-btn img {
  display: block;
  width: 24px;
  height: 24px;
  opacity: 0.6;
}

@media (max-width: 360px) {
  [data-ui-unit="E1"] .e1-title {
    font-size: 16px;
  }
  [data-ui-unit="E1"] .e1-tools {
    gap: 12px;
  }
  [data-ui-unit="E1"] .e1-tool-btn img {
    width: 20px;
    height: 20px;
  }
}

E2.css:
[data-ui-unit="E2"] .search-label {
  display: block;
  font-size: 14px;
  font-weight: 500;
  color: #283548;
  margin-bottom: 8px;
}

[data-ui-unit="E2"] .search-surface {
  display: flex;
  align-items: center;
  background-color: #ffffff;
  border-radius: 12px;
  min-height: 46px;
  padding: 0 16px;
}

[data-ui-unit="E2"] .search-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  opacity: 0.5;
}

[data-ui-unit="E2"] input#search {
  flex: 1;
  min-width: 0;
  background: transparent;
  border: none;
  padding: 0;
  margin-left: 12px;
  color: #283548;
  font-family: inherit;
  font-size: 14px;
}

[data-ui-unit="E2"] input#search::placeholder {
  color: #9aa3b0;
}

[data-ui-unit="E2"] input#search:focus-visible {
  outline: none;
}

E3.css:
[data-ui-unit="E3"].e3-wrapper {
  --ink: #283548;
  --muted: #566273;
  --surface: #fff;
}

[data-ui-unit="E3"] .e3-group {
  border: none;
  padding: 0;
  margin: 0;
  min-height: 36px;
}

[data-ui-unit="E3"] .e3-legend {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

[data-ui-unit="E3"] .e3-chips {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  padding: 12px 0;
}

[data-ui-unit="E3"] .e3-chip {
  font: 500 14px/1.57 "Noto Sans KR", sans-serif;
  background: var(--surface);
  color: var(--muted);
  border-radius: 18px;
  padding: 0 12px;
  min-height: 36px;
  cursor: default;
  white-space: nowrap;
}

[data-ui-unit="E3"] .e3-chip--active {
  background: var(--ink);
  color: var(--surface);
}

E4a.css:
[data-ui-unit="E4a"].e4a-card {
    background: var(--surface, #fff);
    border-radius: 14px;
    padding: 16px;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

[data-ui-unit="E4a"] .e4a-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    min-width: 0;
    position: relative;
}

[data-ui-unit="E4a"] .e4a-avatar-group {
    display: flex;
    align-items: center;
    min-width: 0;
    flex: 1;
}

[data-ui-unit="E4a"] .e4a-avatar {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    object-fit: cover;
    flex-shrink: 0;
}

[data-ui-unit="E4a"] .e4a-info {
    display: flex;
    flex-direction: column;
    margin-left: 8px;
    min-width: 0;
}

[data-ui-unit="E4a"] .e4a-name {
    font-family: "Noto Sans KR", sans-serif;
    font-size: 18px;
    line-height: 24px;
    font-weight: 700;
    color: var(--ink, #283548);
    margin: 0;
    padding: 0;
    white-space: nowrap;
}

[data-ui-unit="E4a"] .e4a-meta {
    display: flex;
    align-items: center;
    margin-top: 2px;
    font-size: 14px;
    line-height: 1.5;
    color: var(--muted, #566273);
    min-width: 0;
}

[data-ui-unit="E4a"] .e4a-icon-bookmark {
    width: 14px;
    height: 14px;
    flex-shrink: 0;
    margin-right: 4px;
}

[data-ui-unit="E4a"] .e4a-badge {
    background-color: #e6f0ff;
    color: var(--blue, #365bcc);
    font-size: 12px;
    line-height: 20px;
    padding: 1px 6px;
    border-radius: 6px;
    white-space: nowrap;
}

[data-ui-unit="E4a"] .e4a-divider {
    width: 1px;
    height: 14px;
    background-color: #dce1e8;
    margin: 0 8px;
    display: inline-block;
    vertical-align: middle;
}

[data-ui-unit="E4a"] .e4a-role {
    white-space: nowrap;
}

[data-ui-unit="E4a"] .e4a-favorite {
    background: transparent;
    border: none;
    padding: 0;
    margin-left: 8px;
    cursor: pointer;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-top: -2px;
}

[data-ui-unit="E4a"] .e4a-icon-heart {
    width: 24px;
    height: 24px;
    fill: var(--red, #e85260);
}

[data-ui-unit="E4a"] .e4a-body {
    margin-top: 16px;
}

[data-ui-unit="E4a"] .e4a-body label {
    display: block;
    font-size: 14px;
    color: var(--muted, #566273);
    margin-bottom: 6px;
}

[data-ui-unit="E4a"] #e4a-desc {
    width: 100%;
    resize: none;
    border: 1px solid transparent;
    background: transparent;
    color: var(--ink, #283548);
    padding: 0;
    font-family: "Noto Sans KR", sans-serif;
    font-size: 14px;
    line-height: 1.57;
    margin: 0;
}

@media (prefers-reduced-motion: reduce) {
    [data-ui-unit="E4a"].e4a-card, [data-ui-unit="E4a"] .e4a-icon-heart {
        transition: none !important;
        animation: none !important;
    }
}
